from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='La célula es la unidad de estructura y función de los seres vivos. Este capítulo presenta la teoría celular, distingue las células procariotas de las eucariotas, da órdenes de magnitud de sus tamaños y explica por qué el tamaño de una célula no es arbitrario, para llegar a un cálculo sencillo de la relación entre superficie y volumen.',
        quotes=[Q('es_celula','De hecho, la célula es el elemento de menor tamaño que puede considerarse vivo.'), Q('en_cell','The cell is the basic structural and functional unit of all forms of life or organisms.')]))
    P.append(dict(text='Las células se descubrieron en 1665, cuando Robert Hooke las observó y las llamó así por su parecido con las celdas de un monasterio. La teoría celular se desarrolló a partir de los trabajos de Matthias Schleiden, en 1838 para los vegetales, y de Theodor Schwann, en 1839 para los animales. Postula que todos los organismos están compuestos por una o más células, que la célula es la unidad fundamental de estructura y función de todos los organismos, y que todas las células derivan de otras preexistentes.',
        quotes=[Q('en_cell','Cells were discovered by Robert Hooke in 1665, who named them after their resemblance to cells in a monastery.'), Q('es_celula','La teoría celular, propuesta en 1838 para los vegetales y en 1839 para los animales,','postula que todos los organismos están compuestos por células, y que todas las células derivan de otras precedentes'), Q('en_cell','that cells are the fundamental unit of structure and function in all organisms, and that all cells come from pre-existing cells')]))
    P.append(dict(text='El último postulado se asocia a Rudolf Virchow, que en 1855 afirmó que las células nuevas proceden de otras por división celular, y lo resumió en la frase omnis cellula ex cellula. Con ese postulado cada célula se entiende como descendiente de otra. Eso explica por qué la división celular y la replicación del ADN, que se estudian en los capítulos siguientes, ocupan un lugar central en la biología.',
        quotes=[Q('en_cell','1855: Rudolf Virchow stated that new cells come from pre-existing cells by cell division (omnis cellula ex cellula)'), Q('es_celula','todas las células derivan de otras precedentes')]))
    P.append(dict(text='Los organismos se agrupan en procariotas y eucariotas. Las células procariotas, que son las de las bacterias y las arqueas, no tienen un núcleo rodeado por una membrana y poseen en cambio una región llamada nucleoide. En las células eucariotas, el núcleo está encerrado por la membrana nuclear y hay además otros orgánulos delimitados por membranas, como las mitocondrias, que proporcionan energía a la célula, y los cloroplastos de las plantas, que producen azúcares por fotosíntesis. Los organismos procariotas son unicelulares, mientras que los eucariotas pueden ser unicelulares o pluricelulares.',
        quotes=[Q('en_cell','Prokaryotes lack a membrane-bound nucleus and have a nucleoid instead.'), Q('en_cell','Eukaryotic cells contain other membrane-bound organelles such as mitochondria, which provide energy for cell functions'), Q('nhgri_cell','A eukaryote has a nucleus and membrane-bound organelles, while a prokaryote does not.')]))
    P.append(dict(text='El tamaño varía en órdenes de magnitud. Una fuente indica que las células suelen medir unos 10 µm y tener una masa de 1 ng, aunque existen células mucho mayores. La célula más pequeña observada en condiciones normales es Mycoplasma genitalium, de 0,2 µm, cerca del límite teórico de 0,17 µm. Los procariotas más pequeños miden entre 0,1 y 5,0 µm de diámetro, y existen bacterias de 1 a 2 µm de longitud; en cambio, la bacteria más grande conocida, Thiomargarita magnifica, es visible a simple vista, con una longitud media de 1 cm.',
        quotes=[Q('es_celula','Las células suelen poseer un tamaño de 10 µm y una masa de 1 ng, aunque existen células mucho mayores.'), Q('es_celula','más pequeña observada, en condiciones normales, corresponde a Mycoplasma genitalium, de 0,2 μm, encontrándose cerca del límite teórico de 0,17 μm'), Q('en_cell','Most prokaryotes are the smallest of all organisms, ranging from 0.1 to 5.0 μm in diameter.'), Q('en_cell','The largest bacterium known, Thiomargarita magnifica, is visible to the naked eye with an average length of 1 cm')]))
    P.append(dict(text='Entre las células humanas hay también una gran variedad: los glóbulos rojos miden unas 7 micras, los hepatocitos 20 micras, los espermatozoides 53 µm y los óvulos 150 µm, y algunas neuronas llegan a tener en torno a un metro de longitud. El número de células de un organismo también varía mucho: de unos pocos cientos en algunos nematodos a cientos de billones (10^14) en el ser humano, según una fuente, y entre 10 y 100 billones según otra.',
        quotes=[Q('es_celula','Las células humanas son muy variables: hematíes de 7 micras, hepatocitos con 20 micras, espermatozoides de 53 μm, óvulos de 150 μm'), Q('es_celula','de unos pocos cientos, como en algunos nematodos, a cientos de billones'), Q('nhgri_cell','An adult human body is estimated to contain between 10 and 100 trillion cells.')]))
    P.append(dict(text='Las dos cifras sobre el número de células humanas son compatibles solo si se interpretan con cuidado. En español, un billón es un millón de millones, es decir, 10^12; «cientos de billones» son entonces cientos de 10^12, hasta 10^14. La otra fuente, en inglés, usa trillion con el mismo valor de 10^12 y da entre 10 y 100 de ellos, es decir, entre 10^13 y 10^14. Los dos intervalos coinciden en el extremo superior, y la fuente en español queda con el de mayor magnitud. Es un ejemplo de por qué una cifra con nombre de orden de magnitud debe escribirse también en potencias de diez.',
        quotes=[Q('es_celula','a cientos de billones (1014), como en el caso del ser humano'), Q('nhgri_cell','between 10 and 100 trillion cells')]))
    P.append(dict(text='Las células no pueden crecer sin límite, y una razón es geométrica. Para una célula esférica de radio r, la superficie crece con r al cuadrado y el volumen con r al cubo, de modo que la relación superficie/volumen es 3/r y disminuye al aumentar el radio. Una célula más grande tiene, por unidad de volumen, menos membrana por la que absorber nutrientes y expulsar desechos. Este razonamiento es una inferencia geométrica y no un resultado que las fuentes citen, pero encaja con lo que dicen las fuentes: el tamaño típico es de unos 10 µm y las células mucho mayores son una excepción.',
        quotes=[Q('en_cell','Most cells are only visible under a microscope.'), Q('es_celula','Existen bacterias con 1 y 2 μm de longitud.')]))
    P.append(dict(role='definition', text='Célula: unidad básica de estructura y función de los seres vivos. Una célula procariota carece de núcleo rodeado por membrana; una eucariota tiene núcleo y orgánulos delimitados por membranas.',
        quotes=[Q('nhgri_cell','A cell is the basic building block of living things.'), Q('en_cell','Eukaryotic cells possess a membrane-bound nucleus, and prokaryotic cells lack a nucleus but have a nucleoid region.')]))
    P.append(dict(role='consejo', text='Cuando una fuente dé una magnitud con unidad, como 10 µm o 1 ng, haga un cálculo de plausibilidad antes de usarla. Una esfera de 10 µm de diámetro con una masa de 1 ng tendría una densidad cercana a 1,9 g/cm³, casi el doble de la del agua, lo que indica que las dos cifras son órdenes de magnitud típicos y no medidas de una misma célula.',
        quotes=[Q('es_celula','Las células suelen poseer un tamaño de 10 µm y una masa de 1 ng, aunque existen células mucho mayores.'), Q('en_cell','Most prokaryotes are the smallest of all organisms, ranging from 0.1 to 5.0 μm in diameter.')]))
    P.append(dict(role='self_check', text='¿Qué afirma la teoría celular? ¿En qué se diferencia una célula procariota de una eucariota? ¿Por qué una célula más grande tiene menos superficie por unidad de volumen?',
        quotes=[Q('en_cell','It states that all organisms are composed of one or more cells'), Q('nhgri_cell','All cells can be sorted into one of two groups: eukaryotes and prokaryotes.')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Una fuente da longitudes de 1 a 2 µm para bacterias y de 20 µm para los hepatocitos humanos. Suponiendo células esféricas de diámetro 2 µm y 20 µm, calcule la relación superficie/volumen de cada una y cuántas veces mayor es la de la bacteria.',
        expected='10', quotes=[Q('es_celula','Existen bacterias con 1 y 2 μm de longitud.'), Q('en_cell','Most prokaryotes are the smallest of all organisms, ranging from 0.1 to 5.0 μm in diameter.')],
        method='Relación superficie/volumen de una esfera',
        solution=dict(given=[dict(symbol='d_b',value=2,unit='dimensionless',meaning='diámetro de la bacteria, en µm'),dict(symbol='d_h',value=20,unit='dimensionless',meaning='diámetro del hepatocito, en µm')],
          unknown='La relación superficie/volumen de cada célula y su cociente.',
          model=[dict(name='Esfera de radio r',latex='\\frac{S}{V} = \\frac{4\\pi r^{2}}{\\frac{4}{3}\\pi r^{3}} = \\frac{3}{r}',symbolic='3/r')],
          assumptions=['Las dos células se modelan como esferas, aunque las bacterias suelen ser bastones y los hepatocitos son poliédricos.','El diámetro de la bacteria se toma de la longitud de 2 µm que da la fuente.'],
          development=['El radio es la mitad del diámetro; la relación depende solo del radio.'],
          steps=[dict(text='Relación de la bacteria',equation='S/V = 3/r = 3/1',expression='3/1',expected=3,unit='dimensionless'),
                 dict(text='Relación del hepatocito',equation='S/V = 3/r = 3/10',expression='3/10',expected=0.3,unit='dimensionless'),
                 dict(text='Cociente entre ambas',equation='3 / 0{,}3',expression='3/0.3',expected=10,unit='dimensionless')],
          result='La relación superficie/volumen es 3 µm⁻¹ en la bacteria y 0,3 µm⁻¹ en el hepatocito, y la de la bacteria es 10 veces mayor.',
          interpretation='Por cada unidad de volumen, la bacteria dispone de diez veces más membrana que el hepatocito, lo que favorece el intercambio de sustancias.',
          limitations=['La forma real de las células modifica la relación; el cálculo solo da el orden de magnitud.'],
          mistakes=['Usar el diámetro en vez del radio en 3/r, que divide la relación entre dos.']))]
